/* sombraDeNome devolve a area do quadrado: lado x lado.
   bordaDoQuadrado devolve a borda do quadrado: 4 x lado.

   As duas usam um nome local chamado medida — cada uma o seu. */

int sombraDeNome(int lado) {
    /* 1. declare o nome local medida com a area (lado x lado) */

    /* 2. troque o 0 abaixo: devolva medida */
    return 0;
}

int bordaDoQuadrado(int lado) {
    /* 3. o mesmo aqui: um medida proprio, com 4 x lado, e devolva-o */
    return 0;
}

testsCode:
#include <stdio.h>

/* teste do desafio sombra-de-nome — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Fase VALOR: o teste declara os PROTOTIPOS das caixas do aluno e compara o
   VALOR DEVOLVIDO — o nome local de dentro nao aparece em lugar nenhum aqui,
   porque de fora ele nao existe. */

/* prototipos das funcoes do aluno (o teste declara o que exercita) */
int sombraDeNome(int lado);
int bordaDoQuadrado(int lado);

SM_TEST(a_area_atravessa_a_parede) {
    checa_int("a area do lado 5 e 25", sombraDeNome(5), 25,
              "a conta ficou num nome local e o return trouxe o valor para ca");
}

SM_TEST(a_borda_tem_o_seu_proprio_nome) {
    checa_int("a borda do lado 5 e 20", bordaDoQuadrado(5), 20,
              "o medida desta caixa e outro: 4 x 5, e nao 5 x 5");
    checa_int("a borda do lado 3 e 12", bordaDoQuadrado(3), 12,
              "segundo lado na MESMA caixa: um 20 fixo no return nao passa aqui");
}

SM_TEST(outra_chamada_outro_valor) {
    checa_int("a area do lado 3 e 9", sombraDeNome(3), 9,
              "a cada chamada o nome local nasce de novo, com o lado desta vez");
}

solutionCode:
int sombraDeNome(int lado) {
    int medida = lado * lado;
    return medida;
}

int bordaDoQuadrado(int lado) {
    int medida = 4 * lado;
    return medida;
}
